import type { VerticalTabBarListProps } from "../vertical-tab-bar.types";
import type { TabProps } from "@components/tab-bar";

import { forwardRef, Children, cloneElement, isValidElement, ReactNode } from "react";
import * as RadixTabs from "@radix-ui/react-tabs";
import { clsx } from "clsx";

import { VerticalTabBarClasses } from "../vertical-tab-bar.styles";

const cloneTabsRecursively = (children: ReactNode): ReactNode => {
  return Children.map(children, (child) => {
    if (!isValidElement(child)) {
      return child;
    }

    const newProps: TabProps = {};
    if ((child.type as { displayName?: string })?.displayName === "Tab") {
      newProps.variant = child.props.variant || "vertical";
    }

    if (child.props.children) {
      return cloneElement(child, newProps, cloneTabsRecursively(child.props.children));
    }

    return child;
  });
};

export const VerticalTabBarList = forwardRef<
  HTMLDivElement,
  VerticalTabBarListProps & RadixTabs.TabsListProps
>(({ className, children, ...props }, ref) => {
  const clonedChildren = cloneTabsRecursively(children);

  const hasSections = Children.toArray(children).some(
    (child) =>
      isValidElement(child) &&
      (child.type as { displayName?: string })?.displayName === "VerticalTabBar.Section",
  );

  const conditionalProps = hasSections
    ? {
        "aria-orientation": undefined,
        role: undefined,
      }
    : {};

  return (
    <RadixTabs.List
      ref={ref}
      className={clsx(VerticalTabBarClasses.list, className)}
      {...conditionalProps}
      {...props}
    >
      {clonedChildren}
    </RadixTabs.List>
  );
});

VerticalTabBarList.displayName = "VerticalTabBar.List";
